const markNotificationsRead = `-- name: MarkNotificationsRead :execrows
UPDATE notifications SET read_at = $1
WHERE user_id = $2 AND read_at IS NULL AND ($3::text[] IS NULL OR id = ANY ($3::text[]))
`

type MarkNotificationsReadParams struct {
	Now    *time.Time
	UserID string
	Ids    []string
}

func (q *Queries) MarkNotificationsRead(ctx context.Context, arg MarkNotificationsReadParams) (int64, error) {
	result, err := q.db.Exec(ctx, markNotificationsRead, arg.Now, arg.UserID, arg.Ids)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const reportExists = `-- name: ReportExists :one
SELECT EXISTS (SELECT 1 FROM reports WHERE id = $1)
`

func (q *Queries) ReportExists(ctx context.Context, id string) (bool, error) {
	row := q.db.QueryRow(ctx, reportExists, id)
	var exists bool
	err := row.Scan(&exists)
	return exists, err
}

